-- 📎 Script 214 — A-FEAT-1571: vincula los 24 resúmenes de las tarjetas VISA de MSA 25/26 (Business y Rural, jul-25 → jun-26),
-- copiados del espejo de Ulises (Tarjetas) a la carpeta segura «BANCOS y entidades financieras / BANCO GALICIA SM / extractos 25-26 / Resumenes VISA» y «/ VISA AGRO» (como en 24-25).
-- JMS 06/11: «sí, copiala y vinculá». Escribe 24 filas NUEVAS en public.documentos_respaldo, marca '[script 214]'.
-- Deshacer: 214-vincular-visa-msa-deshacer.sql (sólo las suyas).
begin;
on conflict (empresa, cuenta, periodo, tipo) do nothing;
commit;
select cuenta, count(*) from public.documentos_respaldo where creado_por like '[script 214]%' group by 1;
